INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('1', 'Complete Guide to Home Accessibility Modifications', 'pdf', 'Accessibility Guides', 'https://www.ada.gov/resources/home-modifications.pdf', NULL, '0', 'A comprehensive 50-page guide covering wheelchair ramps, grab bars, doorway widening, and bathroom modifications. Includes cost estimates and contractor recommendations.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('2', 'Assistive Technology for Daily Living', 'video', 'Accessibility Guides', 'https://www.youtube.com/watch?v=assistive-tech-demo', NULL, '0', 'Video series demonstrating the latest assistive devices for cooking, dressing, bathing, and mobility. Features product reviews and where to purchase.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('3', 'Smart Home Automation for Accessibility', 'pdf', 'Technology', 'https://www.accessibility.com/smart-home-guide.pdf', NULL, '0', 'Learn how to set up voice-controlled lights, thermostats, door locks, and appliances. Perfect for individuals with limited mobility.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('4', 'Mental Health Resources for Seniors and PWDs', 'pdf', 'Health & Wellness', 'https://www.mentalhealth.gov/senior-resources.pdf', NULL, '0', 'Directory of mental health professionals specializing in geriatric care and disability support. Includes telehealth options and support groups.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('5', 'Nutrition and Meal Planning for Special Diets', 'pdf', 'Health & Wellness', 'https://www.nutrition.gov/special-diets.pdf', NULL, '0', 'Nutritional guidelines for diabetes, heart disease, and kidney disease. Includes 30 easy-to-prepare recipes and grocery shopping tips.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('6', 'Chair Yoga and Gentle Exercise Routines', 'video', 'Health & Wellness', 'https://www.youtube.com/watch?v=chair-yoga-seniors', NULL, '0', '20-minute video series of low-impact exercises designed for seniors and individuals with mobility limitations. Improves flexibility and strength.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('7', 'Medication Management Guide', 'pdf', 'Health & Wellness', 'https://www.health.gov/medication-management.pdf', NULL, '0', 'Best practices for organizing medications, setting reminders, and understanding drug interactions. Includes printable medication tracker.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('8', 'Understanding Social Security Disability Benefits (SSDI)', 'pdf', 'Legal & Financial', 'https://www.ssa.gov/disability-benefits-guide.pdf', NULL, '0', 'Step-by-step guide to applying for SSDI, eligibility requirements, and what to expect during the application process. Updated for 2026.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('9', 'Medicare and Medicaid Explained', 'pdf', 'Legal & Financial', 'https://www.medicare.gov/coverage-guide.pdf', NULL, '0', 'Clear explanations of coverage options, enrollment periods, and how to maximize your benefits. Includes state-specific information.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('10', 'Estate Planning and Power of Attorney', 'pdf', 'Legal & Financial', 'https://www.legalaid.org/estate-planning.pdf', NULL, '0', 'Essential legal documents every senior should have, including wills, living wills, and healthcare proxies. Includes templates and lawyer referrals.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('11', 'Financial Assistance Programs Directory', 'pdf', 'Legal & Financial', 'https://www.benefits.gov/assistance-programs.pdf', NULL, '0', 'Comprehensive list of federal, state, and local programs offering financial help for housing, utilities, food, and healthcare.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('12', 'Smartphone Basics for Seniors', 'video', 'Technology', 'https://www.youtube.com/watch?v=smartphone-seniors-guide', NULL, '0', 'Easy-to-follow video tutorials on using smartphones for calls, texts, video chats, and emergency alerts. Covers both iPhone and Android.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('13', 'Telehealth: How to Have Virtual Doctor Visits', 'pdf', 'Technology', 'https://www.telehealth.gov/patient-guide.pdf', NULL, '0', 'Guide to setting up and using telehealth platforms like Zoom, Teladoc, and MyChart. Includes troubleshooting tips.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('14', 'Online Safety and Scam Prevention', 'pdf', 'Technology', 'https://www.ftc.gov/online-safety-seniors.pdf', NULL, '0', 'Protect yourself from phishing, identity theft, and online scams. Learn to recognize warning signs and secure your accounts.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('15', 'Local Support Groups and Community Centers', 'pdf', 'Community Support', 'https://www.communityresources.org/support-groups.pdf', NULL, '0', 'Find support groups for caregivers, chronic illness, grief, and more. Includes meeting schedules and contact information.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('16', 'Transportation Services for Seniors and PWDs', 'pdf', 'Community Support', 'https://www.transportation.gov/senior-services.pdf', NULL, '0', 'Directory of paratransit, volunteer driver programs, and accessible taxi services in your area. Includes eligibility and booking info.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('17', 'Volunteer Opportunities and Social Activities', 'pdf', 'Community Support', 'https://www.volunteer.gov/senior-opportunities.pdf', NULL, '0', 'Stay active and engaged! List of volunteer programs, hobby clubs, and social events welcoming seniors and individuals with disabilities.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
INSERT INTO `resources` (`id`, `title`, `type`, `category`, `url`, `file_path`, `is_featured`, `description`, `uploaded_by`, `created_at`, `updated_at`) VALUES ('18', 'Emergency Preparedness for PWDs', 'pdf', 'Community Support', 'https://www.ready.gov/disability-preparedness.pdf', NULL, '0', 'Create a personalized emergency plan including evacuation routes, medication lists, and emergency contacts. Includes printable checklist.', NULL, '2026-01-20 19:22:05', '2026-01-20 19:22:05');
